        ips,pre=tok.split("/",1)
        if pre=="" or not pre.isdigit(): return (None,"bad")
        try: pr=int(pre)
        except: return (None,"bad")
        v4=pv4(ips)
        if v4 is not None:
            if pr<0 or pr>32: return (None,"bad")
            if pr==32: return ([(v4,v4,4)],None)
            if pr==0: return ([(0,0xFFFFFFFF,4)],None)
            mask=(0xFFFFFFFF << (32-pr)) & 0xFFFFFFFF
            st=v4 & mask
            en=st | (~mask & 0xFFFFFFFF)
            return ([(st,en,4)],None)
        else:
            try:
                net=ipaddress.IPv6Network(tok,strict=False)
                st=int(net.network_address)
                pr2=pr
                if pr2==128:
                    return ([(st,st,6)],None)
                sz=1<<(128-pr2)
                en=st+sz-1
                return ([(st,en,6)],None)
            except: return (None,"bad")
    elif "-" in tok:
        idx=tok.rfind("-")
        L=tok[:idx]; R=tok[idx+1:]
        if L=="" or R=="": return (None,"bad")
        lv=pv4(L); rv=pv4(R)
        if lv is not None and rv is not None:
            if lv>rv: return (None,"bad")
            return ([(lv,rv,4)],None)
        try:
            l6=int(ipaddress.IPv6Address(L)); r6=int(ipaddress.IPv6Address(R))
            if l6>r6: return (None,"bad")
            return ([(l6,r6,6)],None)
        except: return (None,"bad")
    else:
        v4=pv4(tok)
        if v4 is not None: return ([(v4,v4,4)],None)
        try:
            v6=int(ipaddress.IPv6Address(tok))
            return ([(v6,v6,6)],None)
        except: return (None,"bad")

def parse_list(s):
    ranges=[]
    toks=s.split(",")
    for t in toks:
        t=t.strip()
        if t=="": continue
        res,err=parse_tok(t)
        if err is not None:
            needs=t.startswith("-")
            return (None,t,needs)
        ranges.extend(res)
    return (ranges,None,False)

def merge_l(lst):
    if not lst: return []
    lst=sorted(lst)
    out=[]
    cs,ce=lst[0][0],lst[0][1]
    for a,b,_ in lst[1:]:
        if a<=ce+1:
            if b>ce: ce=b
        else:
            out.append((cs,ce)); cs,ce=a,b
    out.append((cs,ce))
    return out

def sub_l(base,excl):
    if not excl: return base
    res=[]
    for bs,be in base:
        cur=bs
        for es,ee in excl:
            if ee<cur: continue
            if es>be: break
            if es>cur: res.append((cur,es-1))
            cur=max(cur,ee+1)
            if cur>be: break
        if cur<=be: res.append((cur,be))
    return res

def fmt_v4(s,e):
    if s==e: return fv4(s)
    sz=e-s+1
    if sz & (sz-1) ==0 and s % sz==0:
        bits=sz.bit_length()-1
        pre=32-bits
        if pre==0: return "0.0.0.0/0"
        return f"{fv4(s)}/{pre}"
    return f"{fv4(s)}-{fv4(e)}"

def fmt_v6(s,e):
    if s==e: return str(ipaddress.IPv6Address(s))
    sz=e-s+1
    if sz & (sz-1)==0 and s % sz==0:
        bits=sz.bit_length()-1
        pre=128-bits
        try:
            return str(ipaddress.IPv6Network((s,pre),strict=True))
        except: pass
    return f"{ipaddress.IPv6Address(s)}-{ipaddress.IPv6Address(e)}"

