def top_set(n):
    if n==0: return set()
    if n is None: n=20
    if n==1: n=20
    if n<=len(TOP_RANKING): return set(TOP_RANKING[:n])
    s=set(TOP_RANKING)
    c=1
    while len(s)<n and c<=65535:
        if c not in s: s.add(c)
        c+=1
    return s

def pcap_msg(v,d):
    t=v+d
    if t==0: return PCAP_SIMPLE
    s=""
    for lib in PCAP_LIBS: s+=f"[-] pcap: failed to load: {lib}\n"
    s+=PCAP_SIMPLE
    for f in PCAP_FUNCS: s+=f"pcap: {f}: failed\n"
    if t>=2: s+="pfring: error: dlopen('libpfring.so'): No such file or directory\n"
    return s
