                    cfg.output_format=fmt_map[arg[2]]
                    i+=2
                    continue
                elif arg=="-o":
                    return (cfg,warnings,"nmap(-o): unknown output format\n",None)
                elif arg in ("-oA",):
                    return (cfg,warnings,"nmap(-oA): unsupported output format\n",None)
                elif len(arg)>2 and arg[1]=='o':
                    # attached like "-oXfoo.xml" gave missing filename. Good. So any attached -o* with extra chars => missing filename fatal.
                    return (cfg,warnings,"missing output filename\n",None)
                else:
                    return (cfg,warnings,f"FAIL: unknown option: --{arg[1:]}\n [hint] try \"--help\"\n [hint] ...or, to list nmap-compatible options, try \"--nmap\"\n",None)
            # Unknown short?
            return (cfg,warnings,f"FAIL: unknown option: --{arg[1:]}\n [hint] try \"--help\"\n [hint] ...or, to list nmap-compatible options, try \"--nmap\"\n",None)
        else:
            # positional (IP range)
            # Try to parse as IP? If starts with digit or contains .:/?? Else unknown param fatal?
            # Check: if arg[0].isdigit() or "." in arg or ":" in arg or "/" in arg or "-" in arg and arg[0]!="-"? Actually "-" alone? For "-1" as positional? But "-1" starts with "-", would have been handled as short above? Actually "-1" as arg would be caught as short (starts with "-"), not positional. Good. So positional never starts with "-".
            # For positional like "abc" (no digit, no .:/?? Actually "abc" has no .: etc.), give unknown param fatal.
            # For "123abc" (starts with digit), give bad IP warning (non-fatal).
            # For "10.0.0.256" (contains dots, starts with digit), give bad IP warning.
            # Implement:
            if arg and (arg[0].isdigit() or "." in arg or ":" in arg or "/" in arg):
                res,err=parse_tok(arg)
                if err is not None:
                    warnings.append(f"ERROR: bad IP address/range: {arg}")
                else:
                    for s,e,v in res:
                        if v==4: cfg.ranges_v4.append((s,e))
                        else: cfg.ranges_v6.append((s,e))
                i+=1
                continue
            else:
                return (cfg,warnings,f'FAIL: unknown command-line parameter "{arg}"\n [hint] did you want "--{arg}"?\n',None)
    return (cfg,warnings,None,None)

